INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Ping-Befehl immer auf ICMP beschränkt?', 2, '[{"text": "Ja", "correct": true, "because": "Nutzt ICMP Echo Requests"}, {"text": "Nein", "correct": false, "because": "Standardmäßig ICMP"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel des Ping-Befehls?', 3, '[{"text": "Erreichbarkeit prüfen", "correct": true, "because": "Testet Verbindung zu Host"}, {"text": "Daten übertragen", "correct": false, "because": "Nicht primär"}, {"text": "Manuelle Konfiguration", "correct": false, "because": "Diagnosetool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen liefert der Ping-Befehl?', 5, '[{"text": "Latenzzeit", "correct": true, "because": "Misst Antwortzeit"}, {"text": "Paketverlust", "correct": true, "because": "Zeigt Verbindungsqualität"}, {"text": "Bandbreitenverbrauch", "correct": false, "because": "Nicht gemessen"}, {"text": "Dateigröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ping nutzt ICMP. b) Es zeigt immer die Bandbreite.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) misst keine Bandbreite"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung des Ping-Befehls?', 4, '[{"text": "Antwortzeit", "correct": false, "because": "Zeigt Verbindungsqualität"}, {"text": "Fehlermeldungen", "correct": false, "because": "Hinweisen auf Probleme"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant für Diagnose"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Ping immer eine Antwort garantiert?', 2, '[{"text": "Nein", "correct": true, "because": "Firewalls können Antworten blocken"}, {"text": "Ja", "correct": false, "because": "Antwort nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Parameter ist für den Ping-Befehl entscheidend?', 3, '[{"text": "Ziel-IP", "correct": true, "because": "Bestimmt zu prüfenden Host"}, {"text": "Farbe der Ausgabe", "correct": false, "because": "Kein Parameter"}, {"text": "Manuelle Paketgröße", "correct": false, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Optionen sind beim Ping-Befehl nützlich?', 5, '[{"text": "-c", "correct": true, "because": "Begrenzt Anzahl der Pings"}, {"text": "-t", "correct": true, "because": "Ping bis Abbruch"}, {"text": "-x", "correct": false, "because": "Kein Ping-Parameter"}, {"text": "-z", "correct": false, "because": "Nicht standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ping misst Latenzzeit. b) Es zeigt immer die genaue Ursache von Fehlern. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) liefert keine Ursachen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Ping-Befehl?', 4, '[{"text": "Netzwerkverbindung", "correct": false, "because": "Erforderlich für Test"}, {"text": "Zieladresse", "correct": false, "because": "Bestimmt Host"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Befehlszeile genügt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Funktioniert Ping auch ohne Internet?', 2, '[{"text": "Ja", "correct": true, "because": "Funktioniert in lokalen Netzen"}, {"text": "Nein", "correct": false, "because": "Internet nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Fehler können bei Ping auftreten?', 4, '[{"text": "Host nicht erreichbar", "correct": true, "because": "Zeigt Verbindungsproblem"}, {"text": "Timeout", "correct": true, "because": "Keine Antwort erhalten"}, {"text": "Falsche Farbausgabe", "correct": false, "because": "Kein Ping-Fehler"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Ping immer blockiert wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Firewall ab"}, {"text": "Ja", "correct": false, "because": "Oft erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Nutzung des Ping-Befehls?', 3, '[{"text": "Korrekte Zieladresse", "correct": true, "because": "Sichert genaue Diagnose"}, {"text": "Maximale Paketgröße", "correct": false, "because": "Nicht primär"}, {"text": "Manuelle Wiederholung", "correct": false, "because": "Parameter steuerbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ping kann Paketverlust zeigen. b) Es überträgt große Datenmengen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht primär"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet der Ping-Befehl?', 5, '[{"text": "Schnelle Diagnose", "correct": true, "because": "Prüft Verbindung sofort"}, {"text": "Einfache Nutzung", "correct": true, "because": "Benötigt wenig Parameter"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht unterstützt"}, {"text": "Grafische Ausgabe", "correct": false, "because": "Textbasiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Nutzung von Ping unwichtig?', 3, '[{"text": "Antwortzeit", "correct": false, "because": "Zeigt Verbindungsqualität"}, {"text": "Fehlercodes", "correct": false, "because": "Diagnostizieren Probleme"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Netzwerkfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Ping auf allen Betriebssystemen verfügbar ist?', 2, '[{"text": "Ja", "correct": true, "because": "Standard in Windows, Linux, macOS"}, {"text": "Nein", "correct": false, "because": "Weit verbreitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Misst Ping die Bandbreite eines Netzwerks?', 3, '[{"text": "Nein", "correct": true, "because": "Misst Latenz und Verlust"}, {"text": "Ja", "correct": false, "because": "Andere Tools dafür"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zum Ping-Befehl?', 4, '[{"text": "Prüfung der Servererreichbarkeit", "correct": true, "because": "Typische Anwendung"}, {"text": "Dateikompression", "correct": false, "because": "Andere Tools"}, {"text": "Bildbearbeitung", "correct": false, "because": "Nicht netzwerkbezogen"}]');
